      out.write("            'input[name=\"paymentMethod\"]:checked'\r\n");
      out.write("        );\r\n");
      out.write("\r\n");
      out.write("        if (!selected) {\r\n");
      out.write("            alert(\"Please select a payment method.\");\r\n");
      out.write("            return;\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        const params = new URLSearchParams(window.location.search);\r\n");
      out.write("        const bookingId = params.get(\"bookingId\");\r\n");
      out.write("\r\n");
      out.write("        if (!bookingId || !/^\\d+$/.test(bookingId)) {\r\n");
      out.write("            alert(\"Invalid booking. Please return to My Bookings.\");\r\n");
      out.write("            return;\r\n");
      out.write("        }\r\n");
      out.write("\r\n");
      out.write("        const form = document.createElement(\"form\");\r\n");
      out.write("        form.method = \"POST\";\r\n");
      out.write("        form.action = \"");
      out.print( request.getContextPath() );
      out.write("/DemoPaymentServlet\";\r\n");
      out.write("\r\n");
      out.write("        const fields = {\r\n");
      out.write("            bookingId: bookingId,\r\n");
      out.write("            method: selected.value\r\n");
      out.write("        };\r\n");
      out.write("\r\n");
      out.write("        for (const [name, value] of Object.entries(fields)) {\r\n");
      out.write("            const input = document.createElement(\"input\");\r\n");
